-- DukaanSaathi PostgreSQL schema (demo starter pack)
-- Run against a fresh PostgreSQL database. Prices and inventory are demo data.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE stores (store_id TEXT PRIMARY KEY, store_name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'INR', timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE products (product_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(store_id), sku TEXT NOT NULL, name TEXT NOT NULL, brand TEXT, category TEXT NOT NULL, sale_unit TEXT NOT NULL, pack_size NUMERIC(12,3) NOT NULL, pack_size_unit TEXT NOT NULL, price_inr NUMERIC(12,2) NOT NULL CHECK (price_inr >= 0), is_active BOOLEAN NOT NULL DEFAULT TRUE, description TEXT, UNIQUE(store_id, sku));
CREATE TABLE product_aliases (alias_id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(product_id) ON DELETE CASCADE, alias TEXT NOT NULL, normalized_alias TEXT NOT NULL, language TEXT NOT NULL, alias_type TEXT NOT NULL);
CREATE INDEX idx_alias_normalized ON product_aliases(normalized_alias);
CREATE TABLE inventory (product_id TEXT PRIMARY KEY REFERENCES products(product_id), stock_quantity NUMERIC(12,3) NOT NULL CHECK (stock_quantity >= 0), stock_unit TEXT NOT NULL, low_stock_threshold NUMERIC(12,3) NOT NULL DEFAULT 0, reserved_quantity NUMERIC(12,3) NOT NULL DEFAULT 0 CHECK (reserved_quantity >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE customers (customer_id TEXT PRIMARY KEY, display_name TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_sessions (session_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(store_id), customer_id TEXT REFERENCES customers(customer_id), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','confirmed','expired')), current_cart JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE orders (order_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(store_id), session_id TEXT REFERENCES order_sessions(session_id), customer_id TEXT REFERENCES customers(customer_id), total_amount NUMERIC(12,2) NOT NULL CHECK (total_amount >= 0), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','preparing','ready','completed','rejected','cancelled')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (item_id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(product_id), product_name_snapshot TEXT NOT NULL, quantity NUMERIC(12,3) NOT NULL CHECK (quantity > 0), unit TEXT NOT NULL, unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0), subtotal NUMERIC(12,2) NOT NULL CHECK (subtotal >= 0));
CREATE TABLE stock_movements (movement_id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(product_id), order_id TEXT REFERENCES orders(order_id), change_quantity NUMERIC(12,3) NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
